-- Order-level existence masks are combined before AS; DISTINCT unions memberships by order.
WITH warehouses AS (SELECT cs_order_number AS order_number,cs_warehouse_sk AS warehouse,bit_or(priv_hash(hash(cs_bill_customer_sk))) AS membership FROM main.catalog_sales JOIN main.customer ON cs_bill_customer_sk=c_customer_sk GROUP BY cs_order_number,cs_warehouse_sk),
other_warehouses AS (SELECT a.order_number,a.warehouse,bit_or(b.membership) AS membership FROM warehouses a JOIN warehouses b ON a.order_number=b.order_number AND a.warehouse<>b.warehouse GROUP BY a.order_number,a.warehouse),
return_orders AS (SELECT cr_order_number AS order_number,bit_or(priv_hash(hash(cr_returning_customer_sk))) AS membership FROM main.catalog_returns JOIN main.customer ON cr_returning_customer_sk=c_customer_sk GROUP BY cr_order_number),
input AS (SELECT cs_order_number AS order_number,cs_ext_ship_cost AS shipping,cs_net_profit AS profit,(priv_hash(hash(cs_bill_customer_sk)) & other.membership & ~coalesce(ret.membership,0::UBIGINT)) AS membership
FROM main.catalog_sales JOIN main.customer ON cs_bill_customer_sk=c_customer_sk JOIN main.date_dim ON cs_ship_date_sk=d_date_sk JOIN main.customer_address ON cs_ship_addr_sk=ca_address_sk JOIN main.call_center ON cs_call_center_sk=cc_call_center_sk JOIN other_warehouses other ON cs_order_number=other.order_number AND cs_warehouse_sk=other.warehouse LEFT JOIN return_orders ret ON cs_order_number=ret.order_number WHERE d_date BETWEEN DATE '2002-02-01' AND DATE '2002-04-02' AND ca_state='GA' AND cc_county='Williamson County'),
totals AS (SELECT tpcds_sum(membership,shipping) AS shipping,tpcds_sum(membership,profit) AS profit FROM input),
unique_orders AS (SELECT order_number,bit_or(membership) AS membership FROM input GROUP BY order_number),
counts AS (SELECT tpcds_count(membership,1) AS n FROM unique_orders)
SELECT world,n[world+1] AS order_count,shipping[world+1] AS total_shipping_cost,profit[world+1] AS total_net_profit FROM totals CROSS JOIN counts CROSS JOIN range(64) worlds(world) ORDER BY world;
